  function approveRequest(request,approve){const target=request.entity==='space'?state.spaces.find(s=>s.id===request.targetId):state.nodes.find(n=>n.id===request.targetId);const inheritedAcl=request.entity==='node'&&target?.inherit!==false?Object.fromEntries(state.members.map(m=>[m.id,fileRights(state,target,m.id)])):target?.acl||{};try{check(target,'manage',request.entity);if(approve&&request.entity==='node'&&target.inherit!==false){openModal('permissions',target,'node');setModal({kind:'permissions',item:target,entity:'node',requestId:request.id});setForm(f=>({...f,inherit:false,acl:{...inheritedAcl,[request.userId]:{...NONE,...inheritedAcl[request.userId],view:true}}}));return;}mutate(s=>({...s,requests:s.requests.map(r=>r.id===request.id?{...r,status:approve?'approved':'rejected'}:r),[request.entity==='space'?'spaces':'nodes']:s[request.entity==='space'?'spaces':'nodes'].map(x=>x.id===target.id&&approve?{...x,acl:{...inheritedAcl,[request.userId]:{...NONE,...inheritedAcl[request.userId],view:true}},...(request.entity==='node'?{inherit:false}:{})}:x)}),approve?'批准申请':'拒绝申请',target.name);notify(approve?'已授权查看':'已拒绝申请');}catch(e){notify(e.message);}}

